@using sv_cd9f6efa99e344c1a3a0366183723da2.Services
@namespace sv_cd9f6efa99e344c1a3a0366183723da2.Components.Pages.Settings

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Appearance</h4>

        @if (ShowSuccess)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                Appearance settings saved!
                <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
            </div>
        }

        <!-- Theme -->
        <div class="mb-4">
            <h5>Theme</h5>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                           value="@theme" checked="@(Theme == theme)"
                           @onchange="() => Theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <!-- Font Size -->
        <div class="mb-4">
            <h5>Font Size</h5>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                           value="@size" checked="@(FontSize == size)"
                           @onchange="() => FontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>

        <!-- Language -->
        <div class="mb-4">
            <h5>Language</h5>
            <select class="form-select" style="max-width: 250px;" @bind="Language">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="mb-4">
            <h5>Preview</h5>
            <div class="border rounded p-3 @PreviewClasses" style="@PreviewStyles">
                <h6>Sample Heading</h6>
                <p class="@(CompactMode ? "mb-1" : "mb-3")">This is how your content will look with the selected settings.</p>
                <button class="btn btn-sm btn-primary">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "Light";
    private string FontSize = "Medium";
    private string Language = "English";
    private bool CompactMode;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewClasses => Theme switch
    {
        "Dark" => "bg-dark text-light",
        _ => "bg-white text-dark"
    };

    private string PreviewStyles => FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
    }
}

@page "/settings"
@using sv_cd9f6efa99e344c1a3a0366183723da2.Services
@using sv_cd9f6efa99e344c1a3a0366183723da2.Components.Pages.Settings
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <h2 class="mb-4">Settings</h2>
    <div class="row">
        <div class="col-md-3 col-lg-2 mb-3">
            <SettingsSidebar ActiveSection="@ActiveSection" OnSectionChanged="section => ActiveSection = section" />
        </div>
        <div class="col-md-9 col-lg-10">
            @if (IsLoading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (ActiveSection)
                {
                    case "Profile":
                        <ProfileSection Profile="@Profile" OnSave="SaveProfileAsync" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@Notifications" OnSave="SaveNotificationsAsync" />
                        break;
                    case "Security":
                        <SecuritySection Security="@Security"
                                         OnChangePassword="HandleChangePasswordAsync"
                                         OnRevokeSession="HandleRevokeSessionAsync" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="@Appearance" OnSave="SaveAppearanceAsync" />
                        break;
                }
            }
        </div>
    </div>
</div>

@code {
    private string ActiveSection = "Profile";
    private bool IsLoading = true;

    private UserProfile? Profile;
    private NotificationPrefs? Notifications;
    private SecuritySettings? Security;
    private AppearanceSettings? Appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllAsync();
        IsLoading = false;
    }

    private async Task LoadAllAsync()
    {
        Profile = await SettingsService.GetProfileAsync();
        Notifications = await SettingsService.GetNotificationPrefsAsync();
        Security = await SettingsService.GetSecuritySettingsAsync();
        Appearance = await SettingsService.GetAppearanceAsync();
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        Profile = profile;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        Notifications = prefs;
    }

    private async Task HandleChangePasswordAsync(string passwordData)
    {
        var parts = passwordData.Split('|', 2);
        await SettingsService.ChangePasswordAsync(parts[0], parts[1]);
        Security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        Security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        Appearance = settings;
    }
}

